// spec: .qa/e2e/specs/nav-bar.md · тикеты #8b5196 (подсветка/ореол нижней навигации), #4777a0 (перетекание света между вкладками)
// Роль new10 (онбординг завершён), iPhone 13 Mini (WebKit). Только просмотр: открывается существующий чат new10 без отправки.
// Анимация меряется по кадрам (requestAnimationFrame): положение ореола nav-glow относительно центров вкладок.
// Файл serial: все тесты на одной сессии new10 (refresh-токен одноразовый — сохраняем после каждого теста).
import { test, expect } from '@playwright/test';
import path from 'path';
import { saveSession } from '../_shared/session';
import { TABS, tab, glow, tabCenter, isActive, expectGlowOn, startGlowRecorder, readGlowRecord, analyseSlide, type TabName } from './nav-helpers';

const ROLE = 'new10';
test.use({ storageState: path.resolve(__dirname, '../../../auth', `${ROLE}.json`) });

test.describe('Nav bar תחתון — подсветка активной вкладки и перетекание света', () => {
  test.describe.configure({ mode: 'serial', timeout: 90_000 });

  test.afterEach(async ({ page }) => {
    await saveSession(page, ROLE);
  });

  test('каждая вкладка ведёт на свой маршрут, активна только она и ореол над ней; на «גילוי» ореол скрыт @iphone @prod-safe (#8b5196 #4777a0)', async ({ page }) => {
    await page.goto('/matches');
    await expect(tab(page, 'הודעות')).toBeVisible();
    // Магнит «גילוי» — в центре панели (5 вкладок, по две с каждой стороны).
    const vw = page.viewportSize()!.width;
    expect(Math.abs((await tabCenter(page, 'גילוי')) - vw / 2), 'магнит по центру').toBeLessThanOrEqual(8);

    const order: TabName[] = ['לייקים', 'מיקום', 'חדרים', 'הודעות'];
    for (const name of order) {
      await tab(page, name).click();
      await page.waitForURL((u) => u.pathname === TABS[name]); // AC 6: цели маршрутов не изменились
      await expectGlowOn(page, name); // AC 1: ясная подсветка активной вкладки
      await expect.poll(() => isActive(page, name), { message: `«${name}» активна (белая подпись + залитая иконка)` }).toBe(true);
      for (const other of order.filter((o) => o !== name)) {
        expect(await isActive(page, other), `«${other}» не активна, когда открыта «${name}»`).toBe(false);
      }
    }

    // «גילוי»: свет входит в магнит и исчезает (коммент программиста 10.11, #4777a0).
    await tab(page, 'גילוי').click();
    await page.waitForURL((u) => u.pathname === TABS['גילוי']);
    await expect.poll(async () => (await glow(page))?.op ?? 0, { message: 'ореол скрыт на «גילוי»' }).toBeLessThan(0.05);
  });

  test('«הודעות» → «לייקים»: ореол плавно перетекает (промежуточные кадры, ~300 мс, без скачка), затем вкладка подсвечена @iphone @prod-safe (#4777a0 #8b5196)', async ({ page }) => {
    await page.goto('/matches');
    await expectGlowOn(page, 'הודעות');
    const from = await tabCenter(page, 'הודעות');
    const to = await tabCenter(page, 'לייקים');

    await startGlowRecorder(page, 3000);
    await tab(page, 'לייקים').click();
    const rec = await readGlowRecord(page);
    const a = analyseSlide(rec, from, to);
    test.info().annotations.push({ type: 'glow', description: JSON.stringify(a) });

    expect(a.moving, 'промежуточные кадры между вкладками (не прыжок)').toBeGreaterThanOrEqual(3); // AC 2 / «מה רצוי»
    expect(a.durationMs, 'длительность перехода ~300 мс').toBeGreaterThanOrEqual(150);
    expect(a.durationMs, 'длительность перехода ~300 мс').toBeLessThanOrEqual(700);
    expect(a.backSteps, 'без рывков назад').toBe(0); // AC 3
    expect(a.maxStep, 'без скачка: за кадр меньше 60% пути').toBeLessThan(a.distance * 0.6);

    await page.waitForURL((u) => u.pathname === TABS['לייקים']);
    await expect.poll(() => isActive(page, 'לייקים'), { message: 'иконка и подпись «לייקים» подсвечены' }).toBe(true);
    expect(await isActive(page, 'הודעות')).toBe(false);
  });

  test('«הודעות» → «מיקום» через магнит: одно движение в одну сторону, приходит на «מיקום» @iphone @prod-safe (#4777a0 #8b5196)', async ({ page }) => {
    await page.goto('/matches');
    await expectGlowOn(page, 'הודעות');
    const from = await tabCenter(page, 'הודעות');
    const to = await tabCenter(page, 'מיקום');

    await startGlowRecorder(page, 3000);
    await tab(page, 'מיקום').click();
    const rec = await readGlowRecord(page);
    const a = analyseSlide(rec, from, to);
    test.info().annotations.push({ type: 'glow', description: JSON.stringify(a) });

    expect(a.moving, 'промежуточные кадры (не прыжок)').toBeGreaterThanOrEqual(3);
    expect(a.backSteps, 'одно движение без возврата').toBe(0);
    expect(a.maxStep, 'без скачка через магнит').toBeLessThan(a.distance * 0.6);
    expect(a.durationMs, 'переход завершается быстро').toBeLessThanOrEqual(1000);

    await page.waitForURL((u) => u.pathname === TABS['מיקום']);
    await expectGlowOn(page, 'מיקום');
    await expect.poll(() => isActive(page, 'מיקום')).toBe(true);
  });

  test('возврат из чата («назад»): ореол сразу на «הודעות», не въезжает с края @iphone @prod-safe (#8b5196)', async ({ page }) => {
    await page.goto('/matches');
    await expectGlowOn(page, 'הודעות');
    const target = await tabCenter(page, 'הודעות');

    // Первая беседа в списке (только открыть и вернуться, ничего не отправлять).
    const chatRow = page.getByRole('button').filter({ hasText: /אתמול|היום|\d{1,2}:\d{2}|\d{1,2}\.\d{1,2}/ }).first();
    await expect(chatRow, 'у new10 есть хотя бы одна беседа').toBeVisible();
    await chatRow.click();
    await page.waitForURL((u) => u.pathname !== TABS['הודעות']);

    await startGlowRecorder(page, 2500);
    await page.goBack();
    await page.waitForURL((u) => u.pathname === TABS['הודעות']);
    const rec = await readGlowRecord(page);
    const visible = rec.filter((s) => s.op > 0.05);
    test.info().annotations.push({ type: 'glow', description: JSON.stringify({ frames: rec.length, visible: visible.length, xs: [...new Set(visible.map((s) => Math.round(s.cx)))].slice(0, 20) }) });

    expect(visible.length, 'ореол виден после возврата').toBeGreaterThan(0);
    const off = visible.filter((s) => Math.abs(s.cx - target) > 4);
    expect(off, 'все видимые кадры ореола — над «הודעות» (без въезда с края)').toEqual([]);
    await expect.poll(() => isActive(page, 'הודעות')).toBe(true);
  });

  test('прямой адрес /likes: ореол появляется на месте над «לייקים», без пролёта @iphone @prod-safe (#8b5196)', async ({ page }) => {
    // Запись кадров с самого начала загрузки страницы.
    await page.addInitScript(() => {
      const w = window as unknown as { __qaLoadGlow: { t: number; cx: number; op: number }[] };
      w.__qaLoadGlow = [];
      const t0 = performance.now();
      const frame = (now: number) => {
        const imgs = [...document.querySelectorAll('img[src*="nav-glow"]')] as HTMLElement[];
        const box = imgs.map((i) => i.parentElement?.parentElement).filter((e): e is HTMLElement => !!e && e.getBoundingClientRect().width > 0).pop();
        if (box) {
          const r = box.getBoundingClientRect();
          w.__qaLoadGlow.push({ t: now - t0, cx: r.left + r.width / 2, op: Number(getComputedStyle(box).opacity) });
        }
        if (now - t0 < 12_000) requestAnimationFrame(frame);
      };
      requestAnimationFrame(frame);
    });
    await page.goto('/likes');
    await expectGlowOn(page, 'לייקים');
    const target = await tabCenter(page, 'לייקים');
    const rec = await page.evaluate(() => (window as unknown as { __qaLoadGlow: { t: number; cx: number; op: number }[] }).__qaLoadGlow);
    const visible = rec.filter((s) => s.op > 0.05);
    test.info().annotations.push({ type: 'glow', description: JSON.stringify({ frames: rec.length, visible: visible.length, xs: [...new Set(visible.map((s) => Math.round(s.cx)))].slice(0, 20) }) });

    expect(visible.length).toBeGreaterThan(0);
    expect(visible.filter((s) => Math.abs(s.cx - target) > 4), 'видимый ореол только над «לייקים»').toEqual([]);
    await expect.poll(() => isActive(page, 'לייקים')).toBe(true);
  });
});
